<template>
  <!--
    The change proposals of ONE issue cluster — DOCB-14325.

    The PO's four questions, in order, and then the one control in Touchless
    that writes to a customer's live settings. Everything below is rendering:
    which setting, which value, whether it may be applied at all is decided by
    the backend's `change_proposal` contract and never re-derived here. A
    second opinion in the client is how the UI and the MCP tools would end up
    disagreeing about what DocBits is about to change on a tenant.
  -->
  <div v-if="proposals.length || loading || error" class="change-proposals">
    <div
      v-if="loading"
      class="change-proposal-note"
      data-test="touchless-proposal-loading"
    >
      {{ $t('touchless_proposal_loading') }}
    </div>

    <!-- A failed read costs the proposals and nothing else: the cause, the
         evidence and the fix steps above are computed from recorded pipeline
         evidence and are correct whether or not this endpoint answered. -->
    <div
      v-else-if="error"
      class="change-proposal-note"
      data-test="touchless-proposal-error"
    >
      {{ $t('touchless_proposal_load_failed') }}
    </div>

    <template v-else>
      <div
        v-for="proposal in proposals"
        :key="proposal.proposal_id"
        class="change-proposal"
        data-test="touchless-proposal"
        :data-proposal-id="proposal.proposal_id"
        :data-proposal-status="proposal.status"
      >
        <div class="change-proposal-head">
          <span class="change-proposal-title">
            {{ $t('touchless_proposal_section') }}
          </span>
          <q-chip
            dense
            square
            outline
            :color="riskColor(proposal)"
            :label="riskLabel(proposal)"
            data-test="touchless-proposal-risk-level"
          />
          <q-chip
            dense
            square
            outline
            :label="reversibleLabel(proposal)"
            data-test="touchless-proposal-reversible"
          />
          <span
            class="change-proposal-lift"
            data-test="touchless-proposal-effect-expected"
          >
            {{ expectedEffectLabel(proposal) }}
          </span>
        </div>

        <!-- The four questions. Driven by PROPOSAL_QUESTION_KEYS so the order —
           what is happening, why it matters, what it buys, what it costs — is
           stated once instead of four times in a template. -->
        <div class="change-proposal-questions">
          <div
            v-for="question in questions"
            :key="question.field"
            class="change-proposal-question"
            :data-test="`touchless-proposal-question-${question.field}`"
            :data-question="question.field"
          >
            <div class="change-proposal-question-label">
              {{ $t(question.labelKey) }}
            </div>
            <div class="change-proposal-question-answer">
              {{ proposal.explanation[question.field] }}
            </div>
          </div>
        </div>

        <!-- current → proposed. The proposed half is editable because the reader
           knows their tenant better than the rule that derived the value; the
           current half never is. -->
        <div v-if="showsValueRow(proposal)" class="change-proposal-values">
          <div class="change-proposal-value">
            <span class="change-proposal-value-label">
              {{ $t('touchless_proposal_current_value') }}
            </span>
            <span data-test="touchless-proposal-current">
              {{ displayValue(proposal.current_value) }}
            </span>
          </div>

          <span class="change-proposal-arrow" aria-hidden="true">→</span>

          <div
            class="change-proposal-value"
            data-test="touchless-proposal-proposed"
          >
            <span class="change-proposal-value-label">
              {{ $t('touchless_proposal_proposed_value') }}
            </span>

            <q-toggle
              v-if="valueKind(proposal) === 'boolean'"
              dense
              :model-value="booleanValue(proposal)"
              :label="displayValue(booleanValue(proposal))"
              data-test="touchless-proposal-value-boolean"
              @update:model-value="onValue(proposal, $event)"
            />
            <q-input
              v-else-if="valueKind(proposal) === 'number'"
              dense
              outlined
              type="number"
              class="change-proposal-input"
              :model-value="numberValue(proposal)"
              :suffix="valueUnit(proposal)"
              data-test="touchless-proposal-value-number"
              @update:model-value="onNumber(proposal, $event)"
            />
            <q-input
              v-else
              dense
              outlined
              class="change-proposal-input"
              :model-value="textValue(proposal)"
              data-test="touchless-proposal-value-text"
              @update:model-value="onValue(proposal, $event)"
            />
          </div>
        </div>

        <div class="change-proposal-risk" data-test="touchless-proposal-risk">
          <span class="change-proposal-value-label">
            {{ $t('touchless_proposal_risk') }}
          </span>
          <span>{{ proposal.risk.what_could_go_wrong }}</span>
          <span
            v-if="proposal.risk.compliance_note"
            class="change-proposal-compliance"
          >
            {{ proposal.risk.compliance_note }}
          </span>
        </div>

        <!-- What the backend could NOT resolve. Shown rather than hidden: it is
           the reader's best lead, and a proposal that says nothing about its
           own gap is indistinguishable from one we simply failed to build. -->
        <div
          v-if="proposal.open_questions.length"
          class="change-proposal-questions-open"
          data-test="touchless-proposal-open-questions"
        >
          <span class="change-proposal-value-label">
            {{ $t('touchless_proposal_open_questions') }}
          </span>
          <ul class="change-proposal-list">
            <li v-for="(item, index) in proposal.open_questions" :key="index">
              {{ item }}
            </li>
          </ul>
        </div>

        <!-- ── what can be done about it ─────────────────────────────────── -->

        <!-- Applicable: dry run first, then the write. -->
        <div v-if="isApplicable(proposal)" class="change-proposal-actions">
          <q-btn
            dense
            no-caps
            unelevated
            color="primary"
            icon="visibility"
            :label="$t('touchless_proposal_preview')"
            :loading="stateOf(proposal).previewing"
            :disable="
              stateOf(proposal).previewing || stateOf(proposal).applying
            "
            data-test="touchless-proposal-preview"
            @click="$emit('preview', proposal.proposal_id)"
          />
          <q-btn
            dense
            no-caps
            unelevated
            color="negative"
            icon="play_arrow"
            :label="$t('touchless_proposal_apply')"
            :loading="stateOf(proposal).applying"
            :disable="!canApply(proposal)"
            data-test="touchless-proposal-apply"
            @click="askToConfirm(proposal)"
          >
            <q-tooltip v-if="!canApply(proposal)">
              {{ $t('touchless_proposal_apply_needs_preview') }}
            </q-tooltip>
          </q-btn>
        </div>

        <!-- Not ours to make. The explanation stays — it is what the customer
           forwards to the supplier — but there is nothing to press. -->
        <div
          v-else-if="isSupplierOwned(proposal)"
          class="change-proposal-note"
          data-test="touchless-proposal-supplier"
        >
          {{ $t('touchless_proposal_supplier_action') }}
          <span class="change-proposal-hint">
            {{ $t('touchless_proposal_supplier_hint') }}
          </span>
        </div>

        <!-- The family is certain, the identifier is not. A settings link, never
           a button over a value nobody has determined. -->
        <div
          v-else-if="deepLinkSteps.length"
          class="change-proposal-deep-link"
          data-test="touchless-proposal-deep-link"
        >
          <span class="change-proposal-value-label">
            {{ $t('touchless_proposal_where_to_change') }}
          </span>
          <TouchlessFixStepList
            :steps="deepLinkSteps"
            compact
            data-test-prefix="touchless-proposal-step"
          />
        </div>

        <div
          v-else
          class="change-proposal-note"
          data-test="touchless-proposal-unresolved"
        >
          {{ $t('touchless_proposal_needs_identification') }}
        </div>

        <!-- ── what the dry run said ─────────────────────────────────────── -->

        <div
          v-if="stateOf(proposal).preview"
          class="change-proposal-preview"
          data-test="touchless-proposal-preview-outcome"
        >
          <div data-test="touchless-proposal-preview-result">
            {{
              $t('touchless_proposal_preview_result', {
                count: stateOf(proposal).preview.wouldBeTouchless.count,
                sampled: stateOf(proposal).preview.sampledDocCount,
              })
            }}
          </div>
          <div
            v-if="stateOf(proposal).preview.stillBlocked.length"
            data-test="touchless-proposal-preview-blocked"
          >
            {{
              $t('touchless_proposal_preview_blocked', {
                count: stateOf(proposal).preview.stillBlocked.length,
              })
            }}
            <!-- The REASONS, not only the count: "2 still blocked" alone is a
               number the reader can do nothing with. -->
            <ul class="change-proposal-list">
              <li
                v-for="reason in blockedReasons(proposal)"
                :key="reason.blocker"
              >
                {{
                  $t('touchless_proposal_still_blocked_by', {
                    count: reason.count,
                    blocker: reason.blocker,
                  })
                }}
              </li>
            </ul>
          </div>
          <div
            v-if="stateOf(proposal).preview.sideEffects.length"
            data-test="touchless-proposal-side-effects"
          >
            <span class="change-proposal-value-label">
              {{ $t('touchless_proposal_side_effects') }}
            </span>
            <ul class="change-proposal-list">
              <li
                v-for="(effect, index) in stateOf(proposal).preview.sideEffects"
                :key="index"
              >
                {{ effect }}
              </li>
            </ul>
          </div>
        </div>

        <!-- The value moved since the dry run, so the token no longer describes
           what would be written. Said here rather than left to a 409 at the
           end of a confirmation dialog. -->
        <div
          v-if="stateOf(proposal).edited && isApplicable(proposal)"
          class="change-proposal-note"
          data-test="touchless-proposal-stale-preview"
        >
          {{ $t('touchless_proposal_preview_stale') }}
        </div>

        <div
          v-if="stateOf(proposal).previewError"
          class="change-proposal-note change-proposal-note--bad"
          data-test="touchless-proposal-preview-error"
        >
          {{ describeError(stateOf(proposal).previewError) }}
        </div>

        <div
          v-if="stateOf(proposal).applyError"
          class="change-proposal-note change-proposal-note--bad"
          data-test="touchless-proposal-apply-error"
        >
          {{ describeError(stateOf(proposal).applyError) }}
        </div>

        <!-- ── what it turned out to be worth ────────────────────────────── -->

        <div
          v-if="stateOf(proposal).outcome"
          class="change-proposal-effect"
          data-test="touchless-proposal-effect"
        >
          <span class="change-proposal-value-label">
            {{ $t('touchless_proposal_effect') }}
          </span>
          <span v-if="effectOf(proposal).measurable">
            {{
              $t('touchless_proposal_effect_delta', {
                delta: formatDeltaPp(effectOf(proposal).deltaPp),
                n: effectOf(proposal).n,
              })
            }}
          </span>
          <!-- Under the minimum sample this stays a sentence, never a 0: a
             touchless rate over three documents is noise wearing a percentage
             sign, and printing it would have somebody revert a change that was
             working. -->
          <span v-else>
            {{ $t('touchless_proposal_effect_not_measurable') }}
            {{
              $t('touchless_proposal_effect_sample', {
                n: effectOf(proposal).n,
              })
            }}
          </span>
        </div>

        <div v-if="stateOf(proposal).changeId" class="change-proposal-actions">
          <q-btn
            flat
            dense
            no-caps
            size="sm"
            icon="undo"
            color="primary"
            :label="$t('touchless_proposal_revert')"
            :loading="stateOf(proposal).reverting"
            :disable="stateOf(proposal).reverting"
            data-test="touchless-proposal-revert"
            @click="$emit('revert', proposal.proposal_id)"
          />
        </div>

        <div
          v-else-if="stateOf(proposal).reverted"
          class="change-proposal-note"
          data-test="touchless-proposal-reverted"
        >
          {{ $t('touchless_proposal_reverted') }}
        </div>
      </div>
    </template>

    <!-- One dialog for the panel, not one per proposal: only one change can be
         being confirmed at a time, and N hidden dialogs is N copies of the
         same wording waiting to drift apart. -->
    <q-dialog
      :model-value="Boolean(confirming)"
      data-test="touchless-proposal-confirm-dialog"
      @update:model-value="onDialogModel"
    >
      <q-card v-if="confirming" data-test="touchless-proposal-confirm">
        <q-card-section class="change-proposal-confirm-title">
          {{ $t('touchless_proposal_confirm_title') }}
        </q-card-section>
        <q-card-section>
          <!-- The two things worth reading twice: what will change, and what
               it costs if we are wrong. -->
          <div class="change-proposal-confirm-what">
            {{ confirming.explanation.what_changes }}
          </div>
          <div class="change-proposal-confirm-risk">
            {{ confirming.risk.what_could_go_wrong }}
          </div>
          <div
            v-if="confirming.risk.compliance_note"
            class="change-proposal-compliance"
          >
            {{ confirming.risk.compliance_note }}
          </div>
          <div class="change-proposal-confirm-diff">
            {{ displayValue(confirming.current_value) }} →
            {{ displayValue(stateOf(confirming).editedValue) }}
          </div>
        </q-card-section>
        <q-card-actions align="right">
          <q-btn
            flat
            no-caps
            :label="$t('touchless_proposal_confirm_cancel')"
            data-test="touchless-proposal-confirm-cancel"
            @click="closeConfirm"
          />
          <q-btn
            unelevated
            no-caps
            color="negative"
            :label="$t('touchless_proposal_confirm_ok')"
            data-test="touchless-proposal-confirm-apply"
            @click="confirmApply"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import TouchlessFixStepList from './TouchlessFixStepList.vue';
import {
  PROPOSAL_QUESTION_KEYS,
  isApplyOffered,
  proposalValueKind,
} from 'src/utils/touchless-proposals';
import type {
  TouchlessChangeProposal,
  TouchlessProposalValueKind,
} from 'src/utils/touchless-proposals';
import type { TouchlessProposalState } from 'src/store/touchless-intelligence.store';
import type { TouchlessFixStep } from 'src/services/analytics/TouchlessService';
import { NO_VALUE } from 'src/utils/touchless-format';

/** Quasar colour per stated risk. Three answers, not a gradient. */
const RISK_COLOR: Record<string, string> = {
  low: 'positive',
  medium: 'warning',
  high: 'negative',
};

/**
 * A neutral state for a proposal the store has not seen yet.
 *
 * Returned rather than null so every binding in the template can read the
 * fields directly. An optional chain in each of them is how a template starts
 * disagreeing with itself about whether "no preview yet" means disabled or
 * hidden.
 */
function neutralState(proposalId: string): TouchlessProposalState {
  return {
    proposalId,
    signature: '',
    editedValue: null,
    edited: false,
    previewing: false,
    preview: null,
    previewOutcome: null,
    previewError: null,
    applying: false,
    applyOutcome: null,
    applyError: null,
    changeId: null,
    outcome: null,
    reverting: false,
    reverted: false,
  };
}

/**
 * The change proposals of one issue cluster: the four-question explanation,
 * the editable `current → proposed` row, the dry run, the write, and what the
 * write turned out to be worth.
 *
 * Presentational on purpose. It owns no request and no token — the store does,
 * because this component lives inside a `q-expansion-item` that unmounts the
 * moment the reader scrolls the list, and a preview token whose only record
 * lived here would turn the mandatory dry run into one the reader has to
 * repeat every time they look away.
 *
 * The one piece of local state is which proposal is being CONFIRMED, which is
 * genuinely a property of this screen and of nothing else.
 */
export default defineComponent({
  name: 'ChangeProposalPanel',

  components: { TouchlessFixStepList },

  props: {
    proposals: {
      type: Array as PropType<TouchlessChangeProposal[]>,
      default: () => [],
    },
    /** Preview/apply state per `proposal_id`, owned by the store. */
    states: {
      type: Object as PropType<Record<string, TouchlessProposalState>>,
      default: () => ({}),
    },
    loading: {
      type: Boolean,
      default: false,
    },
    error: {
      type: String as PropType<string | null>,
      default: null,
    },
    /**
     * Where to go when there is no button: the cluster's own deterministic fix
     * steps (DOCB-14316 enriches these with parameters). Deliberately the
     * SAME steps the card shows above rather than a route derived here — a
     * settings path invented in the client is a 404 with extra confidence.
     */
    deepLinkSteps: {
      type: Array as PropType<TouchlessFixStep[]>,
      default: () => [],
    },
  },

  emits: ['preview', 'apply', 'revert', 'update-value'],

  data() {
    return {
      /** The proposal awaiting confirmation, or null. */
      confirming: null as TouchlessChangeProposal | null,
    };
  },

  computed: {
    questions() {
      return PROPOSAL_QUESTION_KEYS;
    },
  },

  methods: {
    stateOf(proposal: TouchlessChangeProposal): TouchlessProposalState {
      return (
        this.states[proposal.proposal_id] ?? neutralState(proposal.proposal_id)
      );
    },

    effectOf(proposal: TouchlessChangeProposal) {
      return (
        this.stateOf(proposal).outcome?.effect ?? {
          measurable: false,
          deltaPp: null,
          n: 0,
          baselinePct: null,
          measuredPct: null,
          dataAsOf: null,
          reason: null,
        }
      );
    },

    isApplicable(proposal: TouchlessChangeProposal): boolean {
      return isApplyOffered(proposal);
    },

    /**
     * A supplier has to change what they send.
     *
     * Read from `owner` rather than from the absent endpoint: a proposal can
     * be missing an endpoint for two very different reasons, and the reader
     * needs to know which one — "wait for the supplier" and "we do not know
     * which setting yet" are not the same next step.
     */
    isSupplierOwned(proposal: TouchlessChangeProposal): boolean {
      return proposal.owner === 'supplier';
    },

    valueKind(proposal: TouchlessChangeProposal): TouchlessProposalValueKind {
      return proposalValueKind(proposal);
    },

    /**
     * Apply is pressable only against a fresh, unedited, unspent dry run.
     *
     * The same rule the server enforces with the preview token. Having it here
     * too means the button is dead rather than the refusal arriving as a 409
     * after a confirmation dialog the reader has already read and accepted.
     */
    canApply(proposal: TouchlessChangeProposal): boolean {
      if (!this.isApplicable(proposal)) return false;
      const state = this.stateOf(proposal);
      if (state.edited || state.applying || state.changeId) return false;
      return Boolean(state.preview?.previewToken);
    },

    /** No editable row for a proposal whose value nobody has determined. */
    showsValueRow(proposal: TouchlessChangeProposal): boolean {
      return proposal.status === 'applicable';
    },

    rawValue(proposal: TouchlessChangeProposal): unknown {
      const state = this.states[proposal.proposal_id];
      return state ? state.editedValue : proposal.proposed_value;
    },

    booleanValue(proposal: TouchlessChangeProposal): boolean {
      return this.rawValue(proposal) === true;
    },

    /**
     * The edited value for the number field.
     *
     * Typed as a number so `q-input`'s model type is satisfied; a value that
     * is not numeric falls back to null (an empty field) rather than being
     * coerced to 0, which would show a tolerance nobody proposed.
     */
    numberValue(proposal: TouchlessChangeProposal): number | null {
      const value = this.rawValue(proposal);
      return typeof value === 'number' && Number.isFinite(value) ? value : null;
    },

    textValue(proposal: TouchlessChangeProposal): string {
      const value = this.rawValue(proposal);
      return value === null || value === undefined ? '' : String(value);
    },

    onValue(proposal: TouchlessChangeProposal, value: unknown): void {
      this.$emit('update-value', {
        proposalId: proposal.proposal_id,
        value,
      });
    },

    /**
     * A number field hands back a string. Sent on as a NUMBER, because the
     * setting is numeric and `"10"` would be written as text into a column
     * that means ten.
     */
    onNumber(proposal: TouchlessChangeProposal, value: unknown): void {
      const parsed = Number(value);
      this.onValue(proposal, Number.isFinite(parsed) ? parsed : value);
    },

    /**
     * The unit beside a numeric field, when the setting names one.
     *
     * '' rather than a guess: a tolerance that is not a percentage must not
     * grow a "%" suffix here.
     */
    valueUnit(proposal: TouchlessChangeProposal): string {
      const setting = (proposal.target.setting || '').toUpperCase();
      return setting.includes('TOLERANCE') || setting.includes('PCT')
        ? '%'
        : '';
    },

    /** A value as a reader reads it — never a bare `true`/`null` on screen. */
    displayValue(value: unknown): string {
      if (value === true)
        return this.$t('touchless_proposal_value_true') as string;
      if (value === false)
        return this.$t('touchless_proposal_value_false') as string;
      if (value === null || value === undefined || value === '')
        return NO_VALUE;
      return String(value);
    },

    /**
     * A failure, in words the reader can use.
     *
     * The store hands over either the SERVER's own sentence — a 409 names what
     * changed, and paraphrasing it would cost the only clue anybody has — or
     * one of this feature's own keys when the refusal carried no message. The
     * prefix is what tells the two apart; anything else is printed verbatim.
     */
    describeError(value: string | null): string {
      if (!value) return '';
      if (!value.startsWith('touchless_proposal_')) return value;
      const translated = this.$t(value) as string;
      return translated === value ? value : translated;
    },

    riskColor(proposal: TouchlessChangeProposal): string {
      return RISK_COLOR[String(proposal.risk.level).toLowerCase()] ?? 'grey';
    },

    /**
     * The risk level, translated — or shown verbatim when this build has no
     * wording for a level the backend added.
     */
    riskLabel(proposal: TouchlessChangeProposal): string {
      const level = String(proposal.risk.level).toLowerCase();
      const key = `touchless_proposal_risk_${level}`;
      const translated = this.$t(key) as string;
      return translated === key ? proposal.risk.level : translated;
    },

    reversibleLabel(proposal: TouchlessChangeProposal): string {
      return this.$t(
        proposal.reversible
          ? 'touchless_proposal_reversible_yes'
          : 'touchless_proposal_reversible_no',
      ) as string;
    },

    /** The projection, with the window it was measured over beside it. */
    expectedEffectLabel(proposal: TouchlessChangeProposal): string {
      const effect = proposal.expected_effect;
      return this.$t('touchless_proposal_expected_effect', {
        lift: this.formatDeltaPp(effect.projected_lift_pp),
        docs: effect.documents_in_window,
        days: effect.window_days,
      }) as string;
    },

    /**
     * The blockers that would remain, grouped.
     *
     * Twenty rows each saying "email, invoice_id" is the same fact twenty
     * times; the count beside the reason is what a reader can act on.
     */
    blockedReasons(
      proposal: TouchlessChangeProposal,
    ): { blocker: string; count: number }[] {
      const counts = new Map<string, number>();
      for (const row of this.stateOf(proposal).preview?.stillBlocked ?? []) {
        const blocker =
          row.nextBlocker ||
          (this.$t('touchless_proposal_blocked_unknown') as string);
        counts.set(blocker, (counts.get(blocker) ?? 0) + 1);
      }
      return [...counts.entries()]
        .map(([blocker, count]) => ({ blocker, count }))
        .sort((a, b) => b.count - a.count);
    },

    /**
     * A signed delta in percentage points.
     *
     * Not `formatLiftPp`: that one is for a PROJECTION and always signs `+`,
     * which would render a measured regression as "+-3 pp".
     */
    formatDeltaPp(value: number | null | undefined): string {
      if (typeof value !== 'number' || !Number.isFinite(value)) return NO_VALUE;
      const rounded = Math.round(value * 10) / 10;
      return `${rounded > 0 ? '+' : ''}${rounded} pp`;
    },

    askToConfirm(proposal: TouchlessChangeProposal): void {
      if (!this.canApply(proposal)) return;
      this.confirming = proposal;
    },

    closeConfirm(): void {
      this.confirming = null;
    },

    onDialogModel(value: boolean): void {
      if (!value) this.closeConfirm();
    },

    confirmApply(): void {
      const proposal = this.confirming;
      if (!proposal) return;
      this.confirming = null;
      this.$emit('apply', proposal.proposal_id);
    },
  },
});
</script>

