<template>
  <div class="evidence-doc-list" data-test="touchless-evidence-list">
    <div v-if="!linkableDocIds.length" class="text-caption text-grey-6">
      {{ $t('touchless_no_evidence_docs') }}
    </div>
    <q-list v-else dense>
      <q-item
        v-for="docId in linkableDocIds"
        :key="docId"
        class="evidence-doc-item"
        data-test="touchless-evidence-item"
      >
        <q-item-section>
          <q-item-label class="evidence-doc-id">{{ docId }}</q-item-label>
        </q-item-section>
        <q-item-section side>
          <div class="row items-center q-gutter-xs">
            <q-btn
              v-if="traceRouteAvailable"
              flat
              dense
              no-caps
              size="sm"
              icon="find_in_page"
              :label="$t('touchless_open_trace')"
              :to="traceRoute(docId)"
              :data-test="`touchless-evidence-trace-${docId}`"
            />
            <q-btn
              flat
              dense
              no-caps
              size="sm"
              icon="open_in_new"
              :label="$t('touchless_open_document')"
              :to="documentRoute(docId)"
              :data-test="`touchless-evidence-document-${docId}`"
            />
          </div>
        </q-item-section>
      </q-item>
    </q-list>

    <div
      v-if="unlinkableCount > 0"
      class="text-caption text-grey-6 q-mt-xs"
      data-test="touchless-evidence-unlinkable"
    >
      {{ $t('touchless_evidence_unlinkable', { count: unlinkableCount }) }}
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { RouteLocationRaw } from 'vue-router';
import { isDocumentId } from 'src/utils/touchless-guards';
import {
  TOUCHLESS_TRACE_ROUTE,
  DOCUMENT_VIEW_ROUTE,
} from 'src/router/touchless-routes';

/**
 * Sample documents behind an issue cluster. Evidence doc ids are real
 * `documents.id` UUIDs, so both deep links resolve: the touchless trace (why
 * automation stopped) and the validation screen (what the document looks like).
 *
 * Ids are validated before they become links. An id the backend could not
 * resolve — or anything that is not a UUID at all — is counted, not linked: a
 * button that navigates to a 404 is worse than an honest "2 samples could not
 * be linked".
 */
export default defineComponent({
  name: 'EvidenceDocList',

  props: {
    docIds: {
      type: Array as PropType<string[]>,
      default: () => [],
    },
  },

  computed: {
    linkableDocIds(): string[] {
      return (this.docIds || []).filter((docId) => isDocumentId(docId));
    },

    unlinkableCount(): number {
      return (this.docIds || []).length - this.linkableDocIds.length;
    },

    /**
     * The trace page ships in its own PR; until its route is registered the
     * button is omitted rather than rendered as a link vue-router cannot
     * resolve.
     */
    traceRouteAvailable(): boolean {
      return this.$router.hasRoute(TOUCHLESS_TRACE_ROUTE);
    },
  },

  methods: {
    traceRoute(docId: string): RouteLocationRaw {
      return { name: TOUCHLESS_TRACE_ROUTE, params: { docId } };
    },

    documentRoute(docId: string): RouteLocationRaw {
      return { name: DOCUMENT_VIEW_ROUTE, params: { id: docId } };
    },
  },
});
</script>

<style lang="scss" scoped>
.evidence-doc-item {
  padding-left: 0;
  padding-right: 0;
}

.evidence-doc-id {
  font-family: monospace;
  font-size: 0.75rem;
  word-break: break-all;
}
