<template>
  <div v-if="noSettingsPage || renderableSteps.length" class="fix-step-block">
    <!-- DOCB-14316: some causes have no DocBits screen behind them at all — a
         malformed e-invoice is fixed by the SENDER, a dead ERP by the ERP.
         Steps with no button read as a missing feature; this says, in words,
         that the absence IS the answer. -->
    <div
      v-if="noSettingsPage"
      class="fix-step-no-page"
      :data-test="`${dataTestPrefix}-no-settings-page`"
    >
      <q-icon name="info" size="16px" class="fix-step-no-page-icon" />
      <span>{{ $t('touchless_fix_step_no_settings_page') }}</span>
    </div>

    <!-- Nothing at all when there is nothing to do. An empty numbered list reads
       as "no steps needed", which is a different claim from "we do not know
       the steps" — the caller says which of the two it is. -->
    <ol
      v-if="renderableSteps.length"
      class="fix-step-list"
      :class="{ 'fix-step-list--compact': compact }"
      :data-test="`${dataTestPrefix}-list`"
    >
      <li
        v-for="step in renderableSteps"
        :key="step.position"
        class="fix-step"
        :data-test="`${dataTestPrefix}-${step.position}`"
      >
        <span class="fix-step-index" aria-hidden="true">
          {{ step.position }}
        </span>
        <div class="fix-step-body">
          <div class="fix-step-label">{{ step.label }}</div>
          <div v-if="!compact && step.what" class="fix-step-what">
            {{ step.what }}
          </div>
        </div>
        <q-btn
          v-if="step.route"
          flat
          dense
          no-caps
          size="sm"
          icon="open_in_new"
          :label="$t('touchless_fix_step_open')"
          :to="step.route"
          :data-test="`${dataTestPrefix}-open-${step.position}`"
        />
      </li>
    </ol>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { TouchlessFixStep } from 'src/services/analytics/TouchlessService';
import { isSafeInternalRoute } from 'src/utils/touchless-guards';

/** The router's fallback record. A path that only matches THIS matches nothing. */
const CATCH_ALL_PATH = '/:catchAll(.*)*';

interface RenderableStep {
  position: number;
  label: string;
  what: string;
  /** A validated internal path, or null when the step has no screen behind it. */
  route: string | null;
}

/**
 * "What to change", as a numbered list of steps, each optionally linking to the
 * DocBits screen where the change is made.
 *
 * The link is the point of this component and also its only risk. A step's
 * `route` comes from the API and — once the advisor ships — ultimately from a
 * language model, which in the recorded probes invented plausible menu paths
 * that do not exist. So a route becomes a button only if it survives two
 * independent checks:
 *
 *   1. `isSafeInternalRoute` — same-origin path, no scheme, no `..`, no
 *      whitespace. Rejects `javascript:alert(1)` and `//evil.example` before
 *      they can ever reach a `:to` binding.
 *   2. the ROUTER's own answer — `$router.resolve()` must land on a real
 *      record. Every unknown path resolves through the catch-all
 *      (`routes.ts:2995`), so a path that only matches the catch-all is a 404
 *      with extra steps, and the step is shown WITHOUT a link instead.
 *
 * Same shape as EvidenceDocList's `traceRouteAvailable`: an honest unlinked
 * line beats a button that navigates to a not-found page.
 */
export default defineComponent({
  name: 'TouchlessFixStepList',

  props: {
    steps: {
      type: Array as PropType<TouchlessFixStep[]>,
      default: () => [],
    },
    /** Drops the per-step explanation — for the digest, where space is tight. */
    compact: {
      type: Boolean,
      default: false,
    },
    dataTestPrefix: {
      type: String,
      default: 'touchless-fix-step',
    },
    /**
     * The API's `advice.no_settings_page` (DOCB-14316): this reason code has
     * no settings screen at all, so the missing buttons are the answer and
     * not a gap. Says so in words instead of leaving the reader to guess.
     */
    noSettingsPage: {
      type: Boolean,
      default: false,
    },
  },

  computed: {
    /**
     * Numbered from the ORIGINAL list, so a step that carries only an
     * explanation still occupies its position: "step 3" in a conversation about
     * this cluster has to mean the same step for everyone reading it.
     */
    renderableSteps(): RenderableStep[] {
      return (this.steps || [])
        .map((step, index) => {
          const label = this.stepLabel(step);
          const what = typeof step?.what === 'string' ? step.what.trim() : '';
          return {
            position: index + 1,
            label,
            // A step carrying only `what` has it PROMOTED to the label. Left
            // in place it would then be rendered twice, once in each weight,
            // reading as a step that restates itself.
            what: what === label ? '' : what,
            route: this.stepRoute(step),
          };
        })
        .filter((step) => step.label.length > 0 || step.what.length > 0);
    },
  },

  methods: {
    /**
     * Falls back to the explanation so a label-less step is still readable.
     *
     * `text` is the third fallback (DOCB-14285): it is what the advisor's own
     * schema names the sentence, so an AI-generated step that reaches this
     * component unnormalised still renders its prose instead of a bare number.
     */
    stepLabel(step: TouchlessFixStep | null | undefined): string {
      const label = typeof step?.label === 'string' ? step.label.trim() : '';
      if (label) return label;
      const what = typeof step?.what === 'string' ? step.what.trim() : '';
      if (what) return what;
      return typeof step?.text === 'string' ? step.text.trim() : '';
    },

    /**
     * The path to link to, or null for no link.
     *
     * `$router` is read defensively because this component is mounted in tests
     * without one, and a thrown TypeError here would blank the whole issue
     * card rather than just the button.
     */
    stepRoute(step: TouchlessFixStep | null | undefined): string | null {
      const route = step?.route;
      if (!isSafeInternalRoute(route)) return null;

      const router = this.$router as unknown as
        | { resolve?: (to: string) => { matched?: { path?: string }[] } }
        | undefined;
      if (typeof router?.resolve !== 'function') return route;

      try {
        const resolved = router.resolve(route);
        const matched = resolved?.matched;
        if (!Array.isArray(matched) || matched.length === 0) return null;
        if (matched.some((record) => record?.path === CATCH_ALL_PATH)) {
          return null;
        }
        return route;
      } catch {
        // A path vue-router cannot parse is not a path this app can navigate.
        return null;
      }
    },
  },
});
</script>

