<template>
  <MessageBanner
    v-if="accessDenied"
    :dissmiss_btn="false"
    :back_route="false"
    :message="$t('ACTION_NOT_ALLOWED')"
  />
  <q-page
    v-else-if="accessGranted"
    class="touchless-supplier-detail"
    data-test="touchless-supplier-detail-page"
  >
    <SubHeader
      name="touchless_supplier_diagnosis"
      :label="$t('touchless_supplier_diagnosis')"
      :show_expiry_alert="true"
      :onSearch="false"
      :display_back_button="true"
      :back_to_link="TOUCHLESS_TAB_PATH"
    />

    <div class="q-pa-md">
      <div class="row items-center q-mb-md">
        <div>
          <div class="supplier-name" data-test="touchless-supplier-name">
            {{ supplierName }}
          </div>
          <div class="supplier-key text-grey-6">{{ supplierId }}</div>
        </div>
        <q-space />
        <!--
          DOCB-14337. The page had no action at all: a reader who arrived from
          a tile, saw this supplier's clusters and wanted them explained had to
          go back to the analytics tab and press the org-wide button, which
          analyses whatever the org's top clusters happen to be.

          Disabled rather than hidden when there is nothing to run: a button
          that vanishes leaves the reader wondering whether the feature exists,
          and the readiness block below says why it is refused.
        -->
        <q-btn
          unelevated
          no-caps
          color="primary"
          icon="auto_awesome"
          class="q-mr-sm"
          :label="$t('touchless_diagnose_supplier_ai')"
          :loading="diagnosisRunning"
          :disable="!canDiagnose"
          data-test="touchless-diagnose-supplier"
          @click="onDiagnoseSupplier"
        />
        <q-btn
          flat
          dense
          no-caps
          icon="refresh"
          :label="$t('retry')"
          :loading="loading"
          data-test="touchless-supplier-reload"
          @click="load"
        />
      </div>

      <!--
        What the run just did, in one line. The per-cluster cards below carry
        the real progress and the results; this only has to stop the click
        looking like a no-op when a dispatch was refused or covered nothing.
      -->
      <q-banner
        v-if="diagnosisNotice"
        dense
        class="q-mb-md diagnosis-notice"
        data-test="touchless-diagnosis-notice"
      >
        <template #avatar>
          <q-icon name="info_outline" />
        </template>
        {{ diagnosisNotice }}
      </q-banner>

      <div
        v-if="loadError"
        class="text-center q-pa-xl"
        data-test="touchless-supplier-error"
      >
        <q-icon name="cloud_off" size="56px" color="grey-5" />
        <p class="q-mt-sm text-grey-6">{{ $t('failed_to_load') }}</p>
        <q-btn
          flat
          :label="$t('retry')"
          icon="refresh"
          size="sm"
          @click="load"
        />
      </div>

      <template v-else>
        <!-- Bucket breakdown -->
        <div class="kpi-row q-mb-md" data-test="touchless-supplier-buckets">
          <TouchlessKpiCard
            v-for="bucket in bucketTiles"
            :key="bucket.key"
            :label="bucket.label"
            :value="bucket.count"
            :subtitle="bucket.subtitle"
            :icon="bucket.icon"
            :to="bucket.to"
            :data-test="`touchless-supplier-bucket-${bucket.key}`"
          />
        </div>

        <!--
          DOCB-14337. WHY the page is empty, with the number.

          Reported on dev: four tiles at 0 with "—", "No issue clusters for
          this supplier in this period", a footer reading "0 of 13 documents
          eligible" and thirteen "recent examples" underneath — every statement
          true, the page as a whole unreadable. An empty diagnosis has five
          causes calling for five different actions, and the page rendered all
          of them identically.

          Rendered only while there is nothing to read: once clusters exist the
          cards themselves are the answer.
        -->
        <div
          v-if="readinessMessage"
          class="diagnosis-readiness q-mb-md"
          data-test="touchless-diagnosis-readiness"
        >
          <q-icon name="info_outline" size="20px" class="q-mr-sm" />
          <span>{{ readinessMessage }}</span>
        </div>

        <!--
          DOCB-14348. How this organisation matches purchase-order lines, with
          no document at all: the five stages, the configured rules in priority
          order and the tolerance governing each column. Shown only when at
          least one cluster on this page is a PO-matching cluster, and
          collapsed — it is the reference a reader consults while reading the
          clusters below, not the headline of the page.
        -->
        <q-expansion-item
          v-if="showsPoRuleset"
          dense
          class="q-mb-md"
          :label="$t('po_match_ruleset_section')"
          data-test="touchless-supplier-po-ruleset"
          @show="poRulesetOpened = true"
        >
          <PoMatchExplanationPanel v-if="poRulesetOpened" mode="ruleset" />
        </q-expansion-item>

        <!-- Issue clusters -->
        <TouchlessWidgetWrapper
          :title="$t('touchless_issue_clusters_title')"
          icon="mdi:alert-circle-outline"
          :loading="loading"
          :badge-count="issues.length"
          data-test="touchless-issue-clusters"
        >
          <div v-if="!issues.length" class="widget-empty">
            <span class="text-grey-6 text-caption">
              {{ $t('touchless_no_issue_clusters') }}
            </span>
          </div>
          <div v-else class="q-pa-sm">
            <IssueClusterCard
              v-for="issue in issues"
              :key="issue.issue_signature"
              :issue="issue"
              :advice-run="store.adviceRunFor(issue.issue_signature)"
              :advice-clock="store.adviceClock"
              :default-opened="issue.issue_signature === focusedSignature"
              :window-days="clusterWindowDays"
              :change-proposals="
                store.changeProposalsFor(issue.issue_signature)
              "
              :proposal-states="store.proposalStates"
              :proposals-loading="
                store.changeProposalsLoading[issue.issue_signature] === true
              "
              :proposals-error="
                store.changeProposalsError[issue.issue_signature] || null
              "
              :pipeline="pipelines[issue.issue_signature] || null"
              @generate-advice="onGenerateAdvice"
              @resume-advice="onResumeAdvice"
              @preview-proposal="
                onPreviewProposal(issue.issue_signature, $event)
              "
              @apply-proposal="onApplyProposal(issue.issue_signature, $event)"
              @revert-proposal="onRevertProposal"
              @update-proposal-value="onProposalValue"
            />
          </div>
        </TouchlessWidgetWrapper>

        <!-- Recent examples -->
        <TouchlessWidgetWrapper
          :title="$t('touchless_recent_examples_title')"
          icon="mdi:file-search-outline"
          :loading="loading"
          class="q-mt-md"
          data-test="touchless-recent-examples"
        >
          <div v-if="!recentExamples.length" class="widget-empty">
            <span class="text-grey-6 text-caption">
              {{ $t('touchless_no_evidence_docs') }}
            </span>
          </div>
          <div v-else class="q-pa-sm">
            <EvidenceDocList :doc-ids="recentExampleIds" />
          </div>
        </TouchlessWidgetWrapper>

        <MetricContractFooter
          :data-as-of="diagnosis?.data_as_of || ''"
          :contract-version="diagnosis?.metric_contract_version || ''"
          :population="diagnosis?.population || null"
        />
      </template>
    </div>
  </q-page>
  <!-- Preferences still loading: neither grant nor deny is known yet. -->
  <q-page
    v-else
    class="touchless-supplier-detail q-pa-md"
    data-test="touchless-gate-pending"
  >
    <q-skeleton type="text" width="30%" class="q-mb-md" />
    <q-skeleton type="rect" height="120px" />
  </q-page>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import MessageBanner from 'src/components/MessageBanner.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { pipelineExplanationService, touchlessService } from 'src/services';
import type {
  TouchlessAdvice,
  TouchlessDiagnosisReadiness,
  TouchlessSupplierDiagnosisResponse,
  TouchlessIssue,
  TouchlessRecentExample,
} from 'src/services/analytics/TouchlessService';
import { useTouchlessIntelligenceStore } from 'src/store/touchless-intelligence.store';
import { useTouchlessAccess } from 'src/composables/useTouchlessAccess';
import { TOUCHLESS_TAB_PATH } from 'src/router/touchless-routes';
import { isValidDiagnosisResponse } from 'src/utils/touchless-guards';
import { isUnresolvedSupplier } from 'src/utils/touchless-supplier';
import {
  buildTouchlessDrilldownLocation,
  type TouchlessDrilldownBucket,
  type TouchlessDrilldownLocation,
} from './touchlessDrilldown';
import TouchlessKpiCard from './components/TouchlessKpiCard.vue';
import TouchlessWidgetWrapper from './components/TouchlessWidgetWrapper.vue';
import MetricContractFooter from './components/MetricContractFooter.vue';
import IssueClusterCard from './components/IssueClusterCard.vue';
import { TOUCHLESS_ADVICE_WINDOW_DAYS } from 'src/utils/touchless-advice';
import type { PipelineExplanationResponse } from 'src/services/analytics/PipelineExplanationService';
import { isValidPipelineResponse } from 'src/services/analytics/PipelineExplanationService';
import PoMatchExplanationPanel from './components/PoMatchExplanationPanel.vue';

/** The stages a PO-matching cluster is attributed to. */
const PO_MATCH_STAGES = ['po_lookup', 'po_line_match'];
import EvidenceDocList from './components/EvidenceDocList.vue';

const BUCKET_TILES = [
  {
    key: 'PURE_TOUCHLESS',
    labelKey: 'touchless_kpi_pure',
    icon: 'mdi:gesture-tap-button',
  },
  {
    key: 'AP_TOUCHLESS',
    labelKey: 'touchless_kpi_ap',
    icon: 'mdi:check-decagram-outline',
  },
  {
    key: 'AP_ASSISTED',
    labelKey: 'touchless_kpi_ap_assisted',
    icon: 'mdi:account-edit',
  },
  {
    key: 'PROCESS_EXCEPTION',
    labelKey: 'touchless_kpi_exceptions',
    icon: 'mdi:alert-circle-outline',
  },
] as const;

/**
 * The explanation each readiness state earns, and which of its counts the
 * sentence is about — DOCB-14337.
 *
 * A table rather than a chain of `v-else-if` because the mapping is data: the
 * API decides the state, this decides how to say it, and a state the client
 * does not know about falls through to no explanation rather than to a wrong
 * one.
 *
 * `ready` is deliberately absent — when there are clusters to read, the cards
 * are the answer and a banner above them is noise.
 */
const READINESS_MESSAGES: Record<
  string,
  { key: string; count: keyof TouchlessDiagnosisReadiness }
> = {
  pending_analysis: {
    key: 'touchless_diagnosis_pending_analysis',
    count: 'in_progress_documents',
  },
  no_clusters: {
    key: 'touchless_diagnosis_no_clusters',
    count: 'diagnosable_documents',
  },
  all_touchless: {
    key: 'touchless_diagnosis_all_touchless',
    count: 'terminal_documents',
  },
  not_eligible: {
    key: 'touchless_diagnosis_not_eligible',
    count: 'not_eligible_documents',
  },
  no_documents: {
    key: 'touchless_diagnosis_no_documents',
    count: 'total_documents',
  },
};

/**
 * Diagnosis for one supplier. State is local rather than in the dashboard
 * store: this page is opened for a single supplier at a time and the data is
 * not shared with any other view, so keeping it here avoids a store slice that
 * would go stale behind the user's back.
 */
export default defineComponent({
  name: 'TouchlessSupplierDetail',

  components: {
    MessageBanner,
    SubHeader,
    TouchlessKpiCard,
    TouchlessWidgetWrapper,
    MetricContractFooter,
    IssueClusterCard,
    PoMatchExplanationPanel,
    EvidenceDocList,
  },

  setup() {
    const store = useTouchlessIntelligenceStore();
    const { accessGranted, accessDenied, checkAccess, ensureSettingsLoaded } =
      useTouchlessAccess();
    return {
      store,
      accessGranted,
      accessDenied,
      checkAccess,
      ensureSettingsLoaded,
    };
  },

  data() {
    return {
      // Back goes to the analytics page AND selects the Touchless tab. Without
      // the query the user would land on Status, which is the tab they never
      // came from — a regression the standalone route did not have.
      TOUCHLESS_TAB_PATH,
      loading: false,
      loadError: false,
      // The rule-set panel is mounted on first open, not with the page:
      // it reads the published TOML, and a reader who never expands it
      // should not pay for that read (DOCB-14348).
      poRulesetOpened: false,
      // Ownership token: only the newest load may commit. See load().
      loadGeneration: 0,
      diagnosis: null as TouchlessSupplierDiagnosisResponse | null,
      // DOCB-14351, keyed by issue signature. Owned here rather than in each
      // card so the cards stay presentational and the specs that mount them
      // start no requests.
      pipelines: {} as Record<string, PipelineExplanationResponse>,
      // DOCB-14337. Local, like the diagnosis itself: the per-cluster runs the
      // dispatch starts live in the STORE (so they survive a navigation), and
      // this is only the button's own in-flight state.
      diagnosisRunning: false,
      diagnosisNotice: '' as string,
    };
  },

  computed: {
    supplierId(): string {
      return String(this.$route.params.supplierId || '');
    },

    /**
     * The cluster window the PO-match diagnosis counts over (DOCB-14348).
     *
     * Derived from the filter bar's period rather than defaulted inside the
     * card, so the abort-point bars describe the same weeks as the KPI tiles
     * above them. The clusters API accepts 30 or 90 only; a shorter period
     * reads 30, which is the narrowest window it can answer — reporting a
     * 7-day figure under a 30-day query would be the kind of quiet mismatch
     * this panel exists to avoid.
     */
    /**
     * Whether the rule set is worth offering on this page (DOCB-14348).
     *
     * A supplier whose losses are all classification or export problems has no
     * use for the matching rule set, and a section offering to explain it
     * would point at the wrong screen.
     */
    showsPoRuleset(): boolean {
      return this.issues.some(
        (issue) =>
          PO_MATCH_STAGES.includes(String(issue.stage || '')) ||
          String(issue.reason_code || '').startsWith('PO_'),
      );
    },

    clusterWindowDays(): number {
      const days = Number.parseInt(String(this.store.filters.period), 10);
      return Number.isFinite(days) && days > 30 ? 90 : 30;
    },

    supplierName(): string {
      // DOCB-14333: the unattributed bucket has a key and a name, and both
      // are the literal string `unknown`. This page is a diagnosis of those
      // documents; heading it "unknown" says nothing about them.
      if (
        isUnresolvedSupplier(this.supplierId, this.diagnosis?.supplier_name)
      ) {
        return this.$t('touchless_supplier_unidentified') as string;
      }
      return this.diagnosis?.supplier_name || this.supplierId;
    },

    issues(): TouchlessIssue[] {
      return this.diagnosis?.issues || [];
    },

    /**
     * The cluster the reader was sent to, from `?issue=<signature>`
     * (DOCB-14311).
     *
     * A signature, never rendered and never used to build a request — only
     * compared against the signatures the diagnosis itself returned, so a
     * hand-edited query names nothing and simply expands no card.
     */
    focusedSignature(): string {
      const value = this.$route.query?.issue;
      return typeof value === 'string' ? value : '';
    },

    readiness(): TouchlessDiagnosisReadiness | null {
      return this.diagnosis?.diagnosis_readiness || null;
    },

    /**
     * The sentence under the tiles, or '' for no sentence at all.
     *
     * '' rather than a generic fallback on purpose: an API that has not
     * shipped the block, or one that grew a state this build does not know,
     * must leave the page exactly as it was rather than assert a reason
     * nobody computed.
     */
    readinessMessage(): string {
      const readiness = this.readiness;
      if (!readiness) return '';
      const entry = READINESS_MESSAGES[readiness.state];
      if (!entry) return '';
      const raw = readiness[entry.count];
      const count = typeof raw === 'number' && Number.isFinite(raw) ? raw : 0;
      return this.$t(entry.key, { count }) as string;
    },

    /**
     * Whether there is anything for the advisor to run over.
     *
     * Read from the SERVER's cluster count rather than from `issues.length`:
     * they are the same number today, and tying the button to the count the
     * backend selects from is what keeps it honest if they ever stop being.
     */
    canDiagnose(): boolean {
      if (this.loading || this.diagnosisRunning) return false;
      const readiness = this.readiness;
      if (readiness) return readiness.cluster_count > 0;
      // No readiness block (older API): fall back to what is on screen rather
      // than disabling an action that would have worked.
      return this.issues.length > 0;
    },

    recentExamples(): TouchlessRecentExample[] {
      return this.diagnosis?.recent_examples || [];
    },

    recentExampleIds(): string[] {
      // The guard already rejects a malformed member, so this only has to drop
      // the ones the evidence list could not link anyway.
      return this.recentExamples
        .map((example) => example?.doc_id)
        .filter((docId): docId is string => Boolean(docId));
    },

    bucketTiles(): {
      key: string;
      label: string;
      count: number;
      subtitle: string;
      icon: string;
      to: TouchlessDrilldownLocation | null;
    }[] {
      const buckets = this.diagnosis?.buckets || {};
      return BUCKET_TILES.map((tile) => {
        const bucket = buckets[tile.key];
        return {
          key: tile.key,
          label: this.$t(tile.labelKey) as string,
          count: bucket?.count ?? 0,
          // DOCB-14285: the number was inert. Same builder the analytics-tab
          // tiles use, plus THIS supplier — a supplier-scoped count that
          // opened the org-wide list would be a link to a different number.
          // `count` makes the builder answer null at zero, so an empty list
          // never gets a link.
          to: buildTouchlessDrilldownLocation({
            bucket: tile.key as TouchlessDrilldownBucket,
            period: this.store.filters.period,
            supplierKey: this.supplierId,
            count: bucket?.count ?? 0,
          }),
          // An em dash when the bucket has no share of the rate denominator —
          // IN_PROGRESS and NOT_ELIGIBLE never do. `?? 0` printed "0%", which
          // reads as a measured result rather than an absent one.
          subtitle:
            typeof bucket?.pct === 'number' && Number.isFinite(bucket.pct)
              ? `${Math.round(bucket.pct * 10) / 10}%`
              : '—',
          icon: tile.icon,
        };
      });
    },
  },

  watch: {
    // Reactive gate: loads as soon as access is granted, which on a cold load
    // is after the preferences round rather than at mount.
    accessGranted: {
      immediate: true,
      handler(granted: boolean) {
        if (granted) void this.load();
      },
    },

    // Navigating from one supplier to another reuses this component instance.
    '$route.params.supplierId'(next: string, previous: string) {
      if (next && next !== previous) {
        void this.load();
      }
    },
  },

  async mounted() {
    await this.ensureSettingsLoaded();
  },

  methods: {
    async load(): Promise<void> {
      // Defense in depth: the route-param watcher can re-enter here after the
      // flag was revoked mid-session, and an org-scoped request must not leave
      // the browser in that state. Evaluated fresh, not from the cached
      // computed the template renders from.
      if (!this.checkAccess()) return;

      // The router REUSES this component across supplier ids, so two loads can
      // be in flight at once. Without an ownership token, supplier A resolving
      // after B overwrites B's diagnosis, and A's `finally` clears B's loading
      // flag. Capture the id too: `this.supplierId` has already moved on.
      const supplierId = this.supplierId;
      if (!supplierId) return;
      const generation = ++this.loadGeneration;
      const isCurrent = () => generation === this.loadGeneration;

      this.loading = true;
      this.loadError = false;
      try {
        const result = await touchlessService.getSupplierDiagnosis(
          supplierId,
          this.store.filters.period,
        );
        if (!isCurrent()) return;
        // A resolved auth-error payload would otherwise render as a supplier
        // with zero issues, which reads as "nothing wrong here".
        if (!isValidDiagnosisResponse(result)) {
          throw new Error('Malformed touchless diagnosis response');
        }
        this.diagnosis = result;
        // The proposals of the clusters just rendered (DOCB-14325). Fired
        // after the diagnosis has been committed and deliberately NOT awaited:
        // the diagnosis is the answer this page exists for, and it must be on
        // screen whether or not the proposal endpoint answers.
        void this.loadProposals();
        // The pipeline distribution per cluster (DOCB-14351). Same contract as
        // the proposals above: fired after the diagnosis is committed and not
        // awaited, because the diagnosis is the answer this page exists for
        // and it must be on screen whether or not these answer.
        void this.loadPipelines();
      } catch {
        if (!isCurrent()) return;
        this.loadError = true;
        this.diagnosis = null;
      } finally {
        if (isCurrent()) this.loading = false;
      }
    },

    /**
     * Start the advisor for one cluster.
     *
     * Handed to the STORE, not kept here: the job outlives this page. A reader
     * who clicks, goes to look at one of the sample documents and comes back
     * finds the same run still counting rather than a card that forgot it.
     * Nothing is awaited — the page must stay scrollable and navigable while
     * the model works.
     */
    /**
     * "Diagnose supplier with AI" — DOCB-14337.
     *
     * ONE request. The backend runs the same selection statement the org-wide
     * bulk button runs, narrowed to this supplier and at a minimum cluster
     * size of 1, and hands back the signatures the workers really took. Those
     * go straight to the store, which watches them through the SAME per-cluster
     * poll every other advice run uses — so the results appear on the cards
     * already on screen, with their four-question explanation and change
     * proposals, and they survive the reader navigating away and back.
     *
     * Never re-dispatched per cluster: the server already claimed each one.
     */
    async onDiagnoseSupplier(): Promise<void> {
      if (!this.canDiagnose) return;
      const supplierId = this.supplierId;
      if (!supplierId) return;

      this.diagnosisRunning = true;
      this.diagnosisNotice = '';
      try {
        const result =
          await touchlessService.generateSupplierDiagnosis(supplierId);
        // The reader may have navigated to another supplier while the POST was
        // in flight; the runs are still worth adopting (they are keyed by
        // signature, not by page), but this page's notice is not.
        const stillHere = supplierId === this.supplierId;

        if (result.outcome === 'running' && result.signatures.length) {
          // The advice each card is showing RIGHT NOW is the baseline the poll
          // compares against, so a cluster that already had advice is only
          // reported finished once the model has actually replaced it.
          const current = new Map(
            this.issues.map((issue) => [issue.issue_signature, issue.advice]),
          );
          this.store.adoptAdviceRuns(
            result.signatures.map((signature) => ({
              signature,
              advice: current.get(signature) ?? null,
            })),
          );
          if (stillHere) {
            this.diagnosisNotice = this.$t('touchless_diagnosis_started', {
              count: result.signatures.length,
            }) as string;
          }
          return;
        }

        // Every non-running answer is a sentence, never a silent no-op: the
        // reader clicked and is owed an explanation.
        if (stillHere) {
          this.diagnosisNotice = this.$t(
            result.outcome === 'empty'
              ? 'touchless_diagnosis_nothing_to_analyse'
              : 'touchless_diagnosis_unavailable',
          ) as string;
        }
      } catch (error) {
        // A model or broker outage costs the RUN, never the diagnosis already
        // on screen.
        console.warn(
          `[Touchless] supplier diagnosis dispatch failed for ${supplierId}:`,
          error,
        );
        if (supplierId === this.supplierId) {
          this.diagnosisNotice = this.$t(
            'touchless_diagnosis_unavailable',
          ) as string;
        }
      } finally {
        if (supplierId === this.supplierId) this.diagnosisRunning = false;
      }
    },

    onGenerateAdvice(payload: {
      signature: string;
      advice: TouchlessAdvice | null;
    }): void {
      void this.store.startAdviceGeneration(payload.signature, payload.advice);
    },

    /** "Look again" after a timeout: resume reading, never re-dispatch. */
    onResumeAdvice(payload: { signature: string }): void {
      this.store.resumeAdvicePolling(payload.signature);
    },

    /**
     * Read the change proposals for the clusters on screen (DOCB-14325).
     *
     * One request per cluster, in parallel and all settled: a supplier's
     * diagnosis carries a handful of clusters, and one cluster whose proposals
     * cannot be read must not cost the others theirs. The store keeps any
     * preview already in flight, so a reload does not close Apply under the
     * reader's cursor.
     */
    async loadProposals(): Promise<void> {
      await Promise.allSettled(
        this.issues
          .map((issue) => issue.issue_signature)
          .filter(Boolean)
          .map((signature) => this.store.loadChangeProposals(signature)),
      );
    },

    /**
     * Read the pipeline distribution for the clusters on screen (DOCB-14351).
     *
     * One request per cluster, in parallel and all settled — the same shape as
     * `loadProposals`, and for the same reason: a supplier's diagnosis carries
     * a handful of clusters, and one cluster whose distribution cannot be read
     * must not cost the others theirs.
     *
     * Committed into a fresh object rather than mutated in place so a reload
     * cannot leave a diagram belonging to a cluster that is no longer listed.
     *
     * Wrapped in its own try/catch, and therefore UNABLE TO REJECT. `load()`
     * fires this with `void` — deliberately, so the diagnosis is not held
     * behind it — which also means nothing is left to catch what it throws.
     * `Promise.allSettled` only settles the requests it was handed; a failure
     * raised while *building* them (the services barrel not resolving, an
     * absent export) is raised synchronously in the map callback, escapes
     * allSettled entirely, and would surface as an unhandled rejection that
     * the page's own error path never sees. The pipeline diagram is the one
     * thing on this page allowed to be missing, so it swallows its failures
     * the way `TouchlessDocumentTrace.loadPipeline` does.
     */
    async loadPipelines(): Promise<void> {
      try {
        const signatures = this.issues
          .map((issue) => issue.issue_signature)
          .filter(Boolean);
        const results = await Promise.allSettled(
          signatures.map((signature) =>
            // The SAME window the advice and the cluster reads use, so the
            // bars and the counts beside them describe one population.
            pipelineExplanationService.getClusterPipeline(
              signature,
              TOUCHLESS_ADVICE_WINDOW_DAYS,
            ),
          ),
        );
        const next: Record<string, PipelineExplanationResponse> = {};
        results.forEach((result, index) => {
          if (result.status !== 'fulfilled') return;
          if (!isValidPipelineResponse(result.value)) return;
          next[signatures[index]] = result.value;
        });
        this.pipelines = next;
      } catch {
        // No diagram. The diagnosis this page exists for is already on screen.
        this.pipelines = {};
      }
    },

    /** Dry-run one proposal. Nothing is written. */
    onPreviewProposal(signature: string, proposalId: string): void {
      void this.store.previewChangeProposal(signature, proposalId);
    },

    /**
     * Write one proposal's setting.
     *
     * Only ever reached through the card's confirmation dialog, and refused by
     * the store without a fresh preview token — the button being disabled is
     * the first of the two gates, not the only one.
     */
    onApplyProposal(signature: string, proposalId: string): void {
      void this.store.applyChangeProposal(signature, proposalId);
    },

    onRevertProposal(proposalId: string): void {
      void this.store.revertChangeProposal(proposalId);
    },

    onProposalValue(payload: { proposalId: string; value: unknown }): void {
      this.store.setProposedValue(payload.proposalId, payload.value);
    },
  },
});
</script>

